//! The vault with one deliberate bug per module. Each one compiles natively
//! only (never into the Wasm build) and is used to prove the fuzzer finds
//! that class of bug.
//!
//! All variants share the wrapper generated by `vault_variant!`: it handles
//! the token, the "insufficient funds" check and instance TTL, and delegates
//! the bookkeeping, where the bug lives, to the functions passed in.

use soroban_sdk::{contract, contractimpl, token, Address, Env};

use crate::{harness::Variant, DataKey, VaultError, BUMP_THRESHOLD, BUMP_TO};

macro_rules! vault_variant {
    ($name:ident, deposit = $deposit:expr, withdraw = $withdraw:expr, balance = $balance:expr) => {
        #[contract]
        pub struct $name;

        #[contractimpl]
        impl $name {
            pub fn __constructor(env: Env, token: Address) {
                env.storage().instance().set(&DataKey::Token, &token);
                env.storage().instance().set(&DataKey::Total, &0i128);
                env.storage().instance().extend_ttl(BUMP_THRESHOLD, BUMP_TO);
            }
            pub fn deposit(env: Env, from: Address, amount: i128) -> Result<(), VaultError> {
                env.storage().instance().extend_ttl(BUMP_THRESHOLD, BUMP_TO);
                if amount > 0 && token_client(&env).balance(&from) < amount {
                    return Err(VaultError::InsufficientFunds);
                }
                ($deposit)(&env, from.clone(), amount)?;
                token_client(&env).transfer(&from, &env.current_contract_address(), &amount);
                Ok(())
            }
            pub fn withdraw(env: Env, to: Address, amount: i128) -> Result<(), VaultError> {
                env.storage().instance().extend_ttl(BUMP_THRESHOLD, BUMP_TO);
                ($withdraw)(&env, to.clone(), amount)?;
                token_client(&env).transfer(&env.current_contract_address(), &to, &amount);
                Ok(())
            }
            pub fn transfer(
                _env: Env,
                _from: Address,
                _to: Address,
                _amount: i128,
            ) -> Result<(), VaultError> {
                Err(VaultError::InvalidAmount)
            }
            pub fn balance(env: Env, who: Address) -> i128 {
                ($balance)(&env, &who)
            }
            pub fn total(env: Env) -> i128 {
                env.storage().instance().get(&DataKey::Total).unwrap_or(0)
            }
        }

        impl Variant for $name {
            const HAS_TRANSFER: bool = false;
            fn register(env: &Env, token: &Address) -> Address {
                env.register($name, (token.clone(),))
            }
        }
    };
}

fn token_client(env: &Env) -> token::Client<'_> {
    let id: Address = env.storage().instance().get(&DataKey::Token).unwrap();
    token::Client::new(env, &id)
}

// Correct building blocks shared by the variants.

fn get_balance(env: &Env, who: &Address) -> i128 {
    env.storage()
        .persistent()
        .get(&DataKey::Balance(who.clone()))
        .unwrap_or(0)
}

fn set_balance(env: &Env, who: &Address, v: i128) {
    let key = DataKey::Balance(who.clone());
    env.storage().persistent().set(&key, &v);
    env.storage()
        .persistent()
        .extend_ttl(&key, BUMP_THRESHOLD, BUMP_TO);
}

fn add_total(env: &Env, delta: i128) -> Result<(), VaultError> {
    let t: i128 = env.storage().instance().get(&DataKey::Total).unwrap_or(0);
    let t = t.checked_add(delta).ok_or(VaultError::Overflow)?;
    env.storage().instance().set(&DataKey::Total, &t);
    Ok(())
}

fn checked_deposit(env: &Env, from: Address, amount: i128) -> Result<(), VaultError> {
    from.require_auth();
    if amount <= 0 {
        return Err(VaultError::InvalidAmount);
    }
    let b = get_balance(env, &from)
        .checked_add(amount)
        .ok_or(VaultError::Overflow)?;
    add_total(env, amount)?;
    set_balance(env, &from, b);
    Ok(())
}

fn checked_withdraw(env: &Env, to: Address, amount: i128) -> Result<(), VaultError> {
    to.require_auth();
    if amount <= 0 {
        return Err(VaultError::InvalidAmount);
    }
    let b = get_balance(env, &to);
    if b < amount {
        return Err(VaultError::InsufficientBalance);
    }
    set_balance(env, &to, b - amount);
    add_total(env, -amount)
}

/// Bug 1: `withdraw` never calls `require_auth`, so anyone can pull anyone
/// else's deposit.
pub mod missing_auth {
    use super::*;

    fn withdraw_without_auth(env: &Env, to: Address, amount: i128) -> Result<(), VaultError> {
        if amount <= 0 {
            return Err(VaultError::InvalidAmount);
        }
        let b = get_balance(env, &to);
        if b < amount {
            return Err(VaultError::InsufficientBalance);
        }
        set_balance(env, &to, b - amount);
        add_total(env, -amount)
    }

    vault_variant!(
        MissingAuthVault,
        deposit = checked_deposit,
        withdraw = withdraw_without_auth,
        balance = get_balance
    );
}

/// Bug 2: balances live in `temporary()` storage, which is deleted for
/// good when its TTL runs out.
pub mod temp_storage {
    use super::*;

    fn get_tmp(env: &Env, who: &Address) -> i128 {
        env.storage()
            .temporary()
            .get(&DataKey::Balance(who.clone()))
            .unwrap_or(0)
    }

    fn deposit(env: &Env, from: Address, amount: i128) -> Result<(), VaultError> {
        from.require_auth();
        if amount <= 0 {
            return Err(VaultError::InvalidAmount);
        }
        let b = get_tmp(env, &from)
            .checked_add(amount)
            .ok_or(VaultError::Overflow)?;
        add_total(env, amount)?;
        env.storage().temporary().set(&DataKey::Balance(from), &b);
        Ok(())
    }

    fn withdraw(env: &Env, to: Address, amount: i128) -> Result<(), VaultError> {
        to.require_auth();
        if amount <= 0 {
            return Err(VaultError::InvalidAmount);
        }
        let b = get_tmp(env, &to);
        if b < amount {
            return Err(VaultError::InsufficientBalance);
        }
        env.storage()
            .temporary()
            .set(&DataKey::Balance(to), &(b - amount));
        add_total(env, -amount)
    }

    vault_variant!(
        TempStorageVault,
        deposit = deposit,
        withdraw = withdraw,
        balance = get_tmp
    );
}

/// Bug 3: deposits write persistent balances without `extend_ttl`, so they
/// get archived after the network's minimum TTL.
pub mod no_ttl {
    use super::*;

    fn deposit(env: &Env, from: Address, amount: i128) -> Result<(), VaultError> {
        from.require_auth();
        if amount <= 0 {
            return Err(VaultError::InvalidAmount);
        }
        let b = get_balance(env, &from)
            .checked_add(amount)
            .ok_or(VaultError::Overflow)?;
        add_total(env, amount)?;
        env.storage().persistent().set(&DataKey::Balance(from), &b);
        Ok(())
    }

    vault_variant!(
        NoTtlVault,
        deposit = deposit,
        withdraw = checked_withdraw,
        balance = get_balance
    );
}

/// Bug 4: the deposit fee is computed as `amount * 30 / 10_000`, which
/// overflows (and traps) for large deposits.
pub mod overflow {
    use super::*;

    const FEE_BPS: i128 = 30;

    fn deposit(env: &Env, from: Address, amount: i128) -> Result<(), VaultError> {
        checked_deposit(env, from, amount)?;
        let fee = amount * FEE_BPS / 10_000; // multiply-before-divide overflow
        env.storage().instance().set(&DataKey::DepositCount, &fee);
        Ok(())
    }

    vault_variant!(
        OverflowVault,
        deposit = deposit,
        withdraw = checked_withdraw,
        balance = get_balance
    );
}

/// Bug 5: every deposit is kept as its own entry and balances are computed
/// by reading *all* of them, so the cost of a call grows with history.
pub mod unbounded {
    use super::*;

    fn sum_deposits(env: &Env, who: &Address) -> i128 {
        let s = env.storage().persistent();
        let n: u32 = s.get(&DataKey::DepositCount).unwrap_or(0);
        let mut sum = 0i128;
        for i in 0..n {
            if let Some((owner, amount)) = s.get::<_, (Address, i128)>(&DataKey::Deposit(i)) {
                if owner == *who {
                    sum = sum.wrapping_add(amount);
                }
            }
        }
        // `Balance` holds the total withdrawn.
        sum.wrapping_sub(get_balance(env, who))
    }

    fn deposit(env: &Env, from: Address, amount: i128) -> Result<(), VaultError> {
        from.require_auth();
        if amount <= 0 {
            return Err(VaultError::InvalidAmount);
        }
        sum_deposits(env, &from)
            .checked_add(amount)
            .ok_or(VaultError::Overflow)?;
        add_total(env, amount)?;
        let s = env.storage().persistent();
        let n: u32 = s.get(&DataKey::DepositCount).unwrap_or(0);
        s.set(&DataKey::Deposit(n), &(from, amount));
        s.set(&DataKey::DepositCount, &(n + 1));
        s.extend_ttl(&DataKey::Deposit(n), BUMP_THRESHOLD, BUMP_TO);
        s.extend_ttl(&DataKey::DepositCount, BUMP_THRESHOLD, BUMP_TO);
        Ok(())
    }

    fn withdraw(env: &Env, to: Address, amount: i128) -> Result<(), VaultError> {
        to.require_auth();
        if amount <= 0 {
            return Err(VaultError::InvalidAmount);
        }
        if sum_deposits(env, &to) < amount {
            return Err(VaultError::InsufficientBalance);
        }
        set_balance(env, &to, get_balance(env, &to).wrapping_add(amount));
        add_total(env, -amount)
    }

    vault_variant!(
        UnboundedVault,
        deposit = deposit,
        withdraw = withdraw,
        balance = sum_deposits
    );
}
